import math, time, numpy as np
from aris3_gui.real_pick import PixelCalibration, PickSequence
# ---- 1) 보정: 알려진 호모그래피(회전+축척+약한 원근)로 만든 점 + 픽셀 잡음 0.5 px
rng = np.random.default_rng(0)
Htrue = np.array([[0.0, -1.1, 900.0], [-1.1, 0.0, 700.0], [0.00002, 0.00001, 1.0]])
def truth(u, v):
    q = Htrue @ [u, v, 1]; return q[0]/q[2], q[1]/q[2]
c = PixelCalibration()
for u, v in [(400, 200), (800, 200), (400, 500), (800, 500), (600, 350), (500, 300)]:
    x, y = truth(u, v)
    c.add(u + rng.normal(0, .5), v + rng.normal(0, .5), x, y, 85.0 + rng.normal(0, .3))
    if len(c.points) in (3, 4, 6): print(f"점 {len(c.points)}: {c.summary()}")
errs = [math.dist(c.to_robot(u, v), truth(u, v)) for u, v in [(450, 250), (700, 420), (620, 300)]]
print(f"새 위치 3곳 오차: {', '.join(f'{e:.2f}' for e in errs)} mm")
c.save('/tmp/claude-1000/-home-fc-workspace-team-RobotTeamProject1/2638165a-38a6-4590-bc29-0c656e2593af/scratchpad/calib_test.json')
d = PixelCalibration(); d.load('/tmp/claude-1000/-home-fc-workspace-team-RobotTeamProject1/2638165a-38a6-4590-bc29-0c656e2593af/scratchpad/calib_test.json')
print("저장 → 불러오기 같은 결과:", np.allclose(d.H, c.H), f"Z {d.grasp_z:.1f}")

# ---- 2) 집기 순서: 가짜 로봇
class FakeLink:
    def __init__(s, stop_at=None): s.busy=False; s.last_ok=False; s.calls=[]; s.stop_at=stop_at; s.posx=[500,0,200,0,180,0]; s.gripper={'position':520}
    def move_tcp_to(s, x, y, z, vel, label=None): return s._go(f"이동 {label} z={z:.0f} v={vel:.0f}")
    def gripper_command(s, cmd, pos=0, cur=0, vel=0, label=None): return s._go(f"{label} pos={pos}")
    def _go(s, what):
        s.calls.append(what); s.busy=True; s.last_ok = (len(s.calls) != s.stop_at)
        def done(): time.sleep(0.15); s.busy=False
        import threading; threading.Thread(target=done).start(); return True
    def wait_motion(s):
        time.sleep(0.1)
        while s.busy: time.sleep(0.02)
        return s.last_ok
for stop_at in (None, 3):
    L = FakeLink(stop_at); logs=[]; p = PickSequence(L, logs.append); p.pick(500, -50, 85)
